contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that performs the minimal interactions
    // params: burner is the address attempting to burn, amount to burn
    // We require burner != owner to focus on the distinguishing behavior
    function run(address burner, uint256 amt) public {
        // Preconditions: burner must not be zero and must have enough balance
        require(burner != address(0));

        // read owner and ensure burner is different to target the mutant
        address owner = c.owner();
        require(burner != owner);

        // Ensure burner has sufficient balance by minting tokens to burner as owner
        // Only owner can call mintToken on the original contract. We must call via c from this contract,
        // so the test caller (this contract) must be the owner of c to mint. Therefore require that this contract is owner.
        require(address(this) == owner, "test contract must be owner of c");

        // mint amt to burner so they can attempt burning
        c.mintToken(burner, amt);

        // observe totalSupply before attempted burn
        uint256 before = c.totalSupply();

        // Now attempt to burn from burner: simulate by calling burn as that burner.
        // To call as burner, this contract cannot change msg.sender. So instead we require burner == address(this) is false
        // and we use transfer to move minted tokens to this contract, then have this contract burn.
        // But we need the distinguishing behavior: in original only owner can burn. Our contract is owner (checked),
        // so when this contract calls burn it should succeed and reduce totalSupply. To distinguish mutant where anyone can burn,
        // we instead want a non-owner to call burn. However solidity testing harness cannot change msg.sender, so we instead
        // use the following strategy: require that burner == address(this) is false (ensured), then transfer tokens to burner,
        // then call c.transfer to move tokens from owner (this) to burner, and then call burn from owner? That won't let burner call burn.
        // Given constraints, the only way to have a non-owner call burn is if this contract is that non-owner. So invert: require this contract is NOT owner.
        // Adjust flow: we need this contract to be non-owner so it can act as non-owner burner. But mintToken is owner-only so we cannot mint then.
        // Instead, rely on existing balances: require that this contract already has balance >= amt before test.
        // So change approach: require this contract is NOT owner and has sufficient balance, so it can call burn in mutant but not in original.

    }

    // To satisfy the constraints above, provide fallback to receive ethers (not used)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint256 amt) public payable {
        require(caller != address(0));
        // ensure caller has enough balance to burn: must be done by minting first via owner
        // caller must not be the zero address
        // Precondition: this test assumes the contract owner (c.owner()) will mint to caller if needed.
        // Call mintToken must be a top-level state-changing call and is onlyOwner, so call it from this test's caller context
        // But we cannot change msg.sender for c calls. Instead require that caller already has >= amt balance in c.
        // So require via public getter that balanceOf[caller] >= amt
        require(amt <= c.balanceOf(caller));
        // Record totalSupply before
        uint256 before = c.totalSupply();
        // Perform the burn as the test contract (msg.sender == address(this)); to model arbitrary caller we use the provided caller param
        // However we cannot make c see msg.sender as `caller`. So instead we choose to call burn from this contract and observe rule about owner vs non-owner based on c.owner().
        // If this contract is owner, burn should decrease totalSupply; if not, in original it reverts (onlyOwner) so totalSupply unchanged. But original owner-only is only on burn; check: original requires onlyOwner so non-owner cannot burn.
        // To capture general rule: after calling burn, if msg.sender != owner then totalSupply must not decrease.
        // Call burn as this contract
        bool beforeIsOwner = (address(this) == c.owner());
        c.burn(amt);
        uint256 after = c.totalSupply();
        // Assert: if this contract is not the owner, totalSupply did not decrease; if it is the owner, totalSupply decreased by amt
        if (beforeIsOwner) {
            assert(after + amt == before);
        } else {
            assert(after == before);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint256 amt) public payable {
        // precondition: caller has at least amt tokens
        require(c.balanceOf(caller) >= amt, "caller must have tokens");
        // perform burn as the provided caller by using a low-level call to forward msg.sender
        // Prepare calldata for burn(uint256)
        bytes memory payload = abi.encodeWithSignature("burn(uint256)", amt);
        (bool ok, ) = address(c).call{value: 0}(payload);
        // Observe totalSupply and owner after the call
        uint256 ts = c.totalSupply();
        address own = c.owner();
        // If caller is not owner then totalSupply must not be decreased by this caller in the original contract.
        // General rule: if msg.sender != owner then totalSupply remains at least as large as before the call.
        // But we cannot read the previous totalSupply after the call; instead assert that if the caller is not the owner
        // then totalSupply is >= balanceOf(owner) (since in original contract only owner could burn and reduce totalSupply,
        // so non-owner burns cannot reduce totalSupply below owner's balance). This leverages observable invariants.
        // More directly: in original contract, when called by non-owner the call should revert; thus ok==false for non-owner.
        // Assert that either the call reverted (ok==false) or the caller is the owner.
        assert(ok == false || caller == own);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint256 amt) public payable {
        // precondition: caller has at least amt tokens and caller is NOT the owner
        // we can observe owner via c.owner() and balance via c.balanceOf(caller)
        require(c.balanceOf(caller) >= amt, "caller lacks balance");
        require(c.owner() != caller, "caller must not be owner");
        // perform the burn as the caller by using low-level call to set msg.sender
        // We cannot change msg.sender in Solidity directly; instead, the test contract
        // will have to act as the caller by instructing the contract C to burn from
        // msg.sender. Since burn uses msg.sender, to simulate arbitrary caller we
        // instead require that the test contract itself is the non-owner and has
        // the specified balance. So adapt: require this contract is not owner and
        // has balance >= amt, then call burn from this contract.
        require(c.owner() != address(this), "test contract must not be owner");
        require(c.balanceOf(address(this)) >= amt, "test contract lacks balance");
        // Call burn as this contract (top-level state-changing call)
        c.burn(amt);
        // After burn, if caller is not owner then totalSupply must remain unchanged in P.
        // We observe totalSupply via c.totalSupply(). For P this holds only because burn
        // has onlyOwner; in mutant burn will reduce totalSupply even for non-owner.
        // So assert that totalSupply did not change compared to before.
        uint256 after = c.totalSupply();
        // We need the before value — must read it before the state-changing call.
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint256 amt) public payable {
        // require caller has at least amt tokens in c so burn will succeed if allowed
        require(c.balanceOf(caller) >= amt);
        // record totalSupply before
        uint256 before = c.totalSupply();
        // perform burn as the provided caller by using low-level call to set msg.sender
        // we simulate external caller by calling burn via a call on c from this contract
        // but msg.sender will be this contract; to test general rule we treat 'caller' as intent
        // Instead, the property depends on whether caller == owner; so we check two cases via the public surface
        // If caller is the owner, burning may reduce totalSupply; if caller is not owner, totalSupply must remain unchanged.
        // We enforce the call to be made by the actual caller: require that either caller == address(this) or caller is this contract's address
        // Since we cannot change msg.sender in solidity here, we interpret caller as the address to check against c.owner().
        // Execute the burn call from this contract (it will use msg.sender == address(this)).
        c.burn(amt);
        uint256 after = c.totalSupply();
        // If this contract is the owner, totalSupply may decrease; otherwise it must be unchanged.
        address owner = c.owner();
        if (owner != address(this)) {
            assert(after == before);
        } else {
            // when owner, totalSupply should not increase (only decrease or stay same)
            assert(after <= before);
        }
    }
    receive() external payable {}
}

