pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // Fuzz parameters: actor (address) and amount to burn
    function testFuzz_property(address actor, uint256 amount) public {
        // Keep domain wide but meaningful: actor must be non-zero
        vm.assume(actor != address(0));

        // Give the actor some tokens by having the owner (deployer) mint to them.
        // setUp deployed c with msg.sender as owner (test contract). Use that owner power.
        uint256 mintAmount = type(uint256).max / 2; // large amount to avoid overflow on adds
        c.mintToken(actor, mintAmount);

        // Ensure actor has at least some balance so they can attempt to burn
        vm.assume(c.balanceOf(actor) >= 0);

        // Bound amount to be at most actor's balance to keep burn precondition true
        uint256 bounded = amount % (c.balanceOf(actor) + 1);

        // Record totalSupply before
        uint256 beforeTotal = c.totalSupply();

        // Actor calls burn(bounded)
        vm.prank(actor);
        bool ok;
        try c.burn(bounded) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: after the call, the reduction in totalSupply equals the burned amount
        // In the reference contract, only the owner can burn; in our test the owner is this test contract
        // so if actor == address(this) the call should succeed and totalSupply reduced by bounded.
        // For the reference contract (correct), when actor == address(this) the following holds for all inputs;
        // the mutant still allows others to burn and would make totalSupply differ for some inputs.
        if (actor == address(this)) {
            // must have succeeded and totalSupply decreased exactly by bounded
            assertTrue(ok && c.totalSupply() + bounded == beforeTotal);
        } else {
            // For non-owner actors the reference contract will revert, so ok must be false and totalSupply unchanged
            assertTrue(!ok && c.totalSupply() == beforeTotal);
        }
    }
}

