        // keep wide bounds but avoid zero-address for caller
        vm.assume(caller != address(0));
        // give caller some funds and the contract owner some token balance by default owner (deployer) has all supply 0
        // mint some tokens to caller so burn attempts are admissible
        // make the deployer the owner and mint tokens to deployer and caller
        // deployer is this test contract (msg.sender in setUp), but c.owner() is address(this)

        // mint some tokens to caller by having owner (this) call mintToken
        uint256 mintAmt = bound(amount, 0, type(uint256).max / 2);
        // ensure mintAmt fits reasonably; if zero, still valid
        c.mintToken(caller, mintAmt);

        // Record totalSupply before burn
        uint256 before = c.totalSupply();

        // Try to have caller invoke burn(amount)
        // Caller must have the balance to attempt the burn; we only test admissible attempts
        vm.prank(caller);
        bool ok;
        try c.burn(mintAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = c.totalSupply();

        // General rule (single assertion): In the reference, only the owner can reduce totalSupply via burn;
        // therefore for a non-owner caller, either the burn call fails (ok == false) or totalSupply is unchanged (after == before).
        // This will hold for the correct contract for all inputs; the mutant which removes the owner restriction
        // will let a non-owner succeed and reduce totalSupply (ok == true && after < before) for some inputs.
        if (caller != address(this)) {
            assertTrue(!ok || after == before);
        } else {
            // if caller is owner (address(this) in test), owner is allowed to burn so successful burn may reduce totalSupply
            // in that case the invariant that only owner can reduce totalSupply is vacuously preserved, so assertTrue(true)
            assertTrue(true);
        }
    }
}

