pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // fuzz parameters: an address actor (potential burner) and an amount to burn
    function testFuzz_property(address actor, uint256 amount) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // ensure amount fits in a reasonable bound so arithmetic in contract behaves normally
        amount = bound(amount, 0, type(uint128).max);

        // make owner be address(this) by default because c was constructed in setUp() from this address
        // deposit some tokens to the actor so they could attempt to burn
        // mint some tokens to actor from the owner
        uint256 mintAmt = amount;
        // ensure owner (this) has tokens to mint: mint to actor
        c.mintToken(actor, mintAmt);

        // record totalSupply before the attempted burn
        uint256 before = c.totalSupply();

        // have the fuzzed actor try to call burn(amount)
        // use vm.prank to make the call come from actor
        vm.prank(actor);
        bool ok;
        try c.burn(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // record totalSupply after the attempted burn
        uint256 after = c.totalSupply();

        // SINGLE ASSERTION: For the correct contract, only the owner can reduce totalSupply via burn;
        // therefore, if the caller is not the owner, totalSupply must remain unchanged after their attempt.
        // This assertion reads the contract's public getter totalSupply(). The mutant that removes the
        // onlyOwner restriction will allow some non-owner callers to successfully reduce totalSupply,
        // causing this assertion to fail for those inputs (actor != owner and ok == true and after < before).
        if (actor != address(this)) {
            assertTrue(after == before);
        } else {
            // if actor is the owner, correct behavior allows burning and reducing totalSupply when ok==true
            // so assert that after == before - amount when the call succeeded, else unchanged
            if (ok) {
                assertTrue(after == before - amount);
            } else {
                assertTrue(after == before);
            }
        }
    }
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Drive the contract: caller must be owner of c for burn to succeed.
    // Parameters:
    // - owner: address which must match c.owner() (we require it)
    // - initialSupply: amount previously minted to owner (must be >= burnValue)
    // - burnValue: value to burn
    function run(address owner, uint256 initialSupply, uint256 burnValue) public {
        // Preconditions: the provided owner must match the contract's owner
        require(owner == c.owner());
        // Ensure owner has enough balance: mint initialSupply to owner (owner is c.owner and onlyOwner guard exists)
        // Call mintToken as the owner of this test contract cannot be the token owner; so we require initialSupply to be > 0
        // and we rely on c already having been constructed and potentially funded. To ensure state, call mintToken from owner by
        // assuming test runner arranges msg.sender — but we cannot change msg.sender here, so instead we check balance and require it's sufficient.
        uint256 balBefore = c.balanceOf(owner);
        require(balBefore + 0 >= 0); // no-op to satisfy static reading
        // Require that owner already has at least burnValue so burn won't revert
        require(c.balanceOf(owner) >= burnValue);

        uint256 totalBefore = c.totalSupply();

        // Perform the burn by invoking through this test contract. The burn function is onlyOwner, so this call will revert
        // unless this contract is the owner. To satisfy the constraints, we instead require that the test contract is the owner.
        // Enforce that this contract is c.owner()
        require(address(this) == c.owner());

        // Now call burn (state-changing call must be top-level)
        c.burn(burnValue);

        uint256 totalAfter = c.totalSupply();

        // On the original contract P: totalAfter == totalBefore - burnValue
        // On mutant M: totalAfter == totalBefore - 2*burnValue, violating this assertion when burnValue > 0
        assert(totalAfter + burnValue == totalBefore);
    }

    // Allow contract to receive Ether if needed by test harness
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 burnAmount) public payable {
        // precondition: caller of burn must be the owner of C, so this contract must be the owner
        // require that this contract currently has at least burnAmount to burn
        require(c.balanceOf(address(this)) >= burnAmount, "not enough balance to burn");
        // record owner's balance and totalSupply before burn
        uint256 balBefore = c.balanceOf(address(this));
        uint256 tsBefore = c.totalSupply();
        // perform the state-changing call
        c.burn(burnAmount);
        // record after values
        uint256 balAfter = c.balanceOf(address(this));
        uint256 tsAfter = c.totalSupply();
        // general rule: the decrease in totalSupply equals the decrease in the owner's balance
        assert(tsBefore - tsAfter == balBefore - balAfter);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 value) public payable {
        // require that msg.sender is the owner so that onlyOwner passes when test contract calls burn
        // The C contract sets owner to the account that deployed it; the test harness must supply a C whose owner is this contract
        // We therefore require that this contract already has sufficient balance to burn and that owner balance >= value
        uint256 oldTotal = c.totalSupply();
        uint256 oldOwnerBalance = c.balanceOf(address(this));
        require(oldOwnerBalance >= value);
        // perform the state-changing call
        c.burn(value);
        // After burning, totalSupply should not have decreased by more than the owner's prior balance
        // i.e., oldTotal - newTotal <= oldOwnerBalance  --> newTotal >= oldTotal - oldOwnerBalance
        uint256 newTotal = c.totalSupply();
        assert(newTotal >= oldTotal - oldOwnerBalance);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 value) public payable {
        // require caller of this test to be the owner of C so burn will succeed
        // we can only observe owner via c.owner()
        require(msg.sender == c.owner());
        // read old totalSupply
        uint256 oldTotal = c.totalSupply();
        // perform the burn as owner
        c.burn(value);
        // read new totalSupply
        uint256 newTotal = c.totalSupply();
        // assert that totalSupply decreased by at most value
        assert(newTotal >= oldTotal - value);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 value) public payable {
        // require the caller is the owner of C so burn can succeed
        // we read owner via the public getter
        address owner = c.owner();
        require(owner == msg.sender, "caller must be owner");

        uint256 oldTotal = c.totalSupply();
        // perform the state-changing call that differs between P and M
        c.burn(value);
        uint256 newTotal = c.totalSupply();
        // Assert that totalSupply decreased by exactly the burned amount
        assert(newTotal + value == oldTotal);
    }
    receive() external payable { }
}

