import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(0, 0, 0); }

    function testFuzz_property(uint256 mintAndBurn) public {
        // keep mintAndBurn in a practical wide domain but ensure it's small enough to avoid overflow in decimals logic
        uint256 amount = bound(mintAndBurn, 0, type(uint256).max / 2);

        // The deployed contract's constructor gave the test deployer (address(this)) the initial totalSupply of 0.
        // We need the owner to be able to burn, so mint some tokens to owner first.
        // owner is the deploying address when c was constructed in setUp(), which is address(this).

        // Mint `amount` tokens to owner so burn can succeed for any amount <= amount.
        if (amount > 0) {
            // call mintToken as owner (address(this) is owner)
            c.mintToken(address(this), amount);

            uint256 before = c.totalSupply();

            // burn 'amount' as owner
            bool ok;
            try c.burn(amount) {
                ok = true;
            } catch {
                ok = false;
            }

            // If burn succeeded, the invariant for the correct contract is:
            // totalSupply_after == totalSupply_before - amount
            // We assert that when burn succeeds, this equality holds.
            // This is the single required assertTrue reading c's public getter.
            if (ok) {
                uint256 afterVal = c.totalSupply();
                assertTrue(afterVal == before - amount);
            } else {
                // If burn reverted unexpectedly, assert false to indicate failure in reference; but
                // according to the reference contract, burn as owner with sufficient balance should succeed.
                assertTrue(false);
            }
        } else {
            // amount == 0: burn(0) should leave totalSupply unchanged. Call burn(0) and assert unchanged.
            uint256 before0 = c.totalSupply();
            bool ok0;
            try c.burn(0) {
                ok0 = true;
            } catch {
                ok0 = false;
            }
            if (ok0) {
                uint256 after0 = c.totalSupply();
                assertTrue(after0 == before0);
