    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // We fuzz the burn amount and an adversarial recipient index (we'll create one or two helper accounts via actors)
    // General rule: after a successful burn call, c.totalSupply() must equal the sum of all known balances.
    // We only track balances of two addresses we interact with (owner and other). That is enough because setUp
    // assigns entire initial supply to owner and we then may move some to other before burning, so sum(owner+other)
    // should equal totalSupply after burn.
    function testFuzz_property(uint256 amt, address other) public {
        // keep other wide but not zero address to allow transfers
        vm.assume(other != address(0));

        // arrange initial supply: give owner some supply by redeploy semantics in setUp (c was new C(0,0,0))
        // Note: constructor used initialSupply=0 in setUp; to produce nonzero balances, mint to owner and other
        // We'll mint a bounded amount so arithmetic stays in u256 range but wide enough to catch bug
        uint256 mintToOwner = bound(amt, 0, type(uint128).max);
        // ensure owner has at least mintToOwner
        address owner = address(this);
        // mint tokens to owner and optionally to other via owner-only mintToken
        // we are the owner because c was deployed by this test contract
        if (mintToOwner > 0) {
            c.mintToken(owner, mintToOwner);
        }

        // optionally transfer some to other to create two-balance scenario
        uint256 transferToOther = uint256(uint48(uint256(keccak256(abi.encodePacked(amt, other)))));
        transferToOther = bound(transferToOther, 0, mintToOwner);
        if (transferToOther > 0) {
            // transfer from owner to other
            c.transfer(other, transferToOther);
        }

        // compute balances before burn
        uint256 beforeOwnerBalance = c.balanceOf(owner);
        uint256 beforeOtherBalance = c.balanceOf(other);
        uint256 beforeTotal = c.totalSupply();

        // choose burn amount as fuzzed amt bounded to owner's balance so the call should succeed
        uint256 burnAmount = bound(amt, 0, beforeOwnerBalance);

        // Call burn as owner (we are owner) and record whether it succeeded
        bool ok;
        try c.burn(burnAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful burn, the invariant we assert is: totalSupply == balanceOf(owner) + balanceOf(other)
        // This reads only public getters of c. This holds for the reference for all inputs; the mutant can
        // break it for some fuzzed burnAmount/transfer scenarios.
        if (ok) {
            uint256 a = c.totalSupply();
            uint256 b = c.balanceOf(owner) + c.balanceOf(other);
            assertTrue(a == b);
        } else {
            // If burn reverted, we make no assertion (the universal property quantifies only over successful calls)
            // but to keep single-assert requirement, we assert the vacuous true when not ok.
            assertTrue(true);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract and then assert that if someone burns tokens, totalSupply decreases only when the caller is the owner.
    // We use parameters to pick burner and amount. Minimal calls: possibly mint to burner so they have balance, then try burn.
    function run(address burner, uint256 amt) public {
        // Preconditions to make the test meaningful
        require(burner != address(0));
        // Ensure burner has at least amt tokens by minting from owner (constructor caller of C is presumably owner)
        // c.mintToken is onlyOwner so this call must come from this contract; but this contract is not owner.
        // To keep it general and minimal, rely on possibility that burner already has balance; require view check.
        require(c.balanceOf(burner) >= amt);

        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(burner);

        // Perform burn from burner by invoking burn via this contract calling c.burn on behalf of burner isn't possible.
        // Instead we simulate the external caller by expecting the contract C's burn to be callable by msg.sender directly.
        // So we call c.burn from this contract: msg.sender for c will be this contract. To make this meaningful, require that
        // this contract is the burner address parameter (i.e., burner == address(this)). That lets us check behavior when caller
        // is non-owner vs when caller is owner (owner is c.owner()).
        require(burner == address(this));

        // Decide amount limit
        require(amt > 0 && amt <= beforeBalance);

        // Call burn() — state-changing call must be a top-level statement
        bool ok = c.burn(amt);
        // observe post-state
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(burner);

        // On original P: only owner can call burn, so when this contract (likely non-owner) calls burn, it should revert and ok would be false
        // However our call would revert in P, preventing reaching assert. To produce a checkable property that holds on P and fails on M,
        // we instead assert a relation: if the caller is NOT owner then totalSupply must NOT decrease (i.e., afterTotal == beforeTotal).
        // On P this holds because non-owner call reverts and state unchanged; on M a non-owner can burn their own tokens reducing totalSupply.

        address owner = c.owner();
        if (address(this) != owner) {
            // For non-owner caller, totalSupply must stay the same after attempting burn
            assert(afterTotal == beforeTotal);
        } else {
            // If this contract is owner, then owner is allowed to burn so totalSupply should decrease by amt and balance reduce
            assert(afterTotal == beforeTotal - amt);
            assert(afterBalance == beforeBalance - amt);
        }
    }

    // fallback/receive not used but allowed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint256 value) public payable {
        require(caller != address(0));
        // We must perform the call from this contract, so simulate caller by requiring
        // the test is invoked by that caller (msg.sender). The test harness should
        // arrange msg.sender accordingly. We only observe whether the call reverted.
        bool reverted;
        try c.burn(value) { reverted = false; } catch { reverted = true; }
        // General rule: if the invoker is not the contract owner, burn must revert.
        // We can observe owner via the public getter `owner()` on C.
        assert(reverted || caller == c.owner());
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint256 value) public payable {
        // require that the caller is not the owner according to the public getter
        // If caller equals owner, the property is not applicable, so we require inequality
        require(c.owner() != caller);

        // We must invoke burn from the specified caller. To do that in a test contract
        // we use a low-level call with abi-encoded selector so msg.sender inside c is this contract.
        // But to emulate an external caller distinct from the owner, we require the provided
        // `caller` to be different from c.owner() and also require this contract to be able
        // to act on behalf of that caller by using pre-supplied calldata pattern: since we
        // cannot change msg.sender via Solidity directly, we instead rely on the fact that
        // the mutant removed the onlyOwner modifier causing non-owners to succeed while
        // the original reverts. To drive the difference observable, we call burn from this
        // contract and assert that it reverts whenever c.owner() != address(this). But the
        // rule must quantify over inputs; so we instead require the caller parameter equals
        // address(this) and ensure address(this) is not owner. This lets the test call burn
        // directly and reason about non-owner calls.
        require(caller == address(this));

        require(c.owner() != address(this));

        bool reverted;
        try c.burn(value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: when this contract is not the owner, burn must revert
        assert(reverted == true);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint256 value) public payable {
        require(caller != address(0));
        bool reverted;
        // call burn as the given caller using low-level call to set msg.sender
        // we cannot change msg.sender in Solidity directly; instead we simulate by having this contract call c.burn
        // but we must ensure caller equals the owner for the original to succeed. We observe owner via c.owner().
        // Precondition: test only meaningful when caller != address(this) (since we can't impersonate). We instead assert relation between caller==owner and revert flag.
        try c.burn(value) { reverted = false; } catch { reverted = true; }
        // The rule: if the provided caller equals the contract owner then burn must not revert when invoked by that caller;
        // otherwise burn must revert. Since we cannot change msg.sender to "caller", we compare caller to c.owner() and require that
        // the revert outcome matches whether caller==owner. This encodes that only owner can make burn succeed.
        assert(reverted == (caller != c.owner()));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint256 value) public payable {
        require(caller != address(0));
        bool reverted;
        // perform burn as the provided caller by using low-level call to set msg.sender
        // We cannot change msg.sender in this test directly; instead we rely on observable owner getter.
        // Call burn from this contract (so msg.sender == address(this)) and record whether it reverted.
        try c.burn(value) { reverted = false; } catch { reverted = true; }
        // Read owner via public getter and compare to this contract's address.
        address owner = c.owner();
        // If burn did not revert, then the caller (address(this)) must equal owner.
        assert(reverted || owner == address(this));
    }
    receive() external payable {}
}

