    function setUp() public { c = new C(0, 0, 0); }

    // Fuzzed params: caller address and amount to attempt burning
    function testFuzz_property(address caller, uint256 amt) public {
        // Keep domain wide but sane: caller != address(0) and amt fits into reasonable bounds
        vm.assume(caller != address(0));
        // Ensure caller is not the owner (owner is address(this) at construction)
        vm.assume(caller != address(this));

        // Fund both owner and caller so they may have balances to attempt burn
        // Give owner some tokens (owner already has totalSupply from constructor = 0 here)
        // To create a scenario where a non-owner could burn, first mint tokens to caller via owner
        // Owner is address(this), so we mint to caller using the owner capabilities
        // The reference contract's functions restrict mintToken to onlyOwner, so this is valid
        c.mintToken(caller, 1);

        // Record pre-state
        uint256 preTotal = c.totalSupply();
        uint256 preCallerBal = c.balanceOf(caller);

        // Attempt to burn as caller. We simulate the external caller context.
        bool ok;
        vm.prank(caller);
        try c.burn(amt) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: In the reference contract, only owner can burn, so any non-owner burn
        // attempt must NOT decrease totalSupply below preTotal unless caller was owner.
        // Because we constrained caller != owner, the reference should always keep totalSupply == preTotal.
        // The mutant (which removes onlyOwner) will allow some caller & amt to succeed and reduce totalSupply,
        // making c.totalSupply() < preTotal for some fuzz inputs, thus failing this assertion.
        assertTrue(c.totalSupply() == preTotal);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function driving the test
    function run(address ownerCaller, uint256 initialSupply, uint256 burnAmount) public {
        // Preconditions: use the existing contract state. Require ownerCaller holds at least burnAmount before burn
        // We observe balanceOf(ownerCaller) before and after calling burn as ownerCaller by invoking burn via this contract is not possible.
        // Instead, we require that ownerCaller is the recorded owner and that this contract is that owner by calling c.owner()
        // but we cannot impersonate ownerCaller. So instead we drive using the externally visible owner and call burn from that owner via c by assuming this contract is already the owner in the provided C instance.
        // Ensure this contract is the owner of c
        require(c.owner() == address(this), "test requires this contract to be owner");

        // Ensure sufficient balance for burn
        uint256 before = c.balanceOf(address(this));
        require(before >= burnAmount, "insufficient balance to burn");

        // perform the burn as owner (this contract)
        bool success = c.burn(burnAmount);
        require(success, "burn failed");

        uint256 after = c.balanceOf(address(this));

        // Property: caller's balance decreased by exactly burnAmount
        assert(before - after == burnAmount);
    }

    // fallback/receive to accept ether if needed by tests (not used here)
    receive() external payable {}
}

